function initOccupationsAutocomplete() {
    const occSearch = document.getElementById('empOccupationSearch');
    const occHidden = document.getElementById('empOccupation');
    const occList = document.getElementById('occDropdownList');

    const codeSearch = document.getElementById('empOccupationCodeSearch');
    const codeHidden = document.getElementById('empOccupationCode');
    const codeList = document.getElementById('codeDropdownList');

    if (!occSearch || !codeSearch) return;

    function renderList(listElement, items, isCode) {
        if (!listElement) return;
        listElement.innerHTML = '';
        if (items.length === 0) {
            const noRes = document.createElement('div');
            noRes.className = 'no-results';
            noRes.textContent = 'لا توجد نتائج';
            listElement.appendChild(noRes);
        } else {
            const displayItems = items.slice(0, 80);
            displayItems.forEach(item => {
                const div = document.createElement('div');
                div.className = 'dropdown-item';
                div.textContent = isCode ? (item.code + ' - ' + item.name) : (item.name + ' (' + item.code + ')');
                div.addEventListener('mousedown', (e) => {
                    e.preventDefault();
                    occSearch.value = item.name;
                    if (occHidden) occHidden.value = item.name;
                    codeSearch.value = item.code;
                    if (codeHidden) codeHidden.value = item.code;
                    if (occList) occList.style.display = 'none';
                    if (codeList) codeList.style.display = 'none';
                });
                listElement.appendChild(div);
            });
        }
    }

    occSearch.addEventListener('focus', () => {
        renderList(occList, window.occArray, false);
        if (occList) occList.style.display = 'block';
    });

    occSearch.addEventListener('input', (e) => {
        const val = e.target.value.trim().toLowerCase();
        const filtered = val ? window.occArray.filter(o => o.name.toLowerCase().includes(val)) : window.occArray;
        renderList(occList, filtered, false);
        if (occList) occList.style.display = 'block';
    });

    occSearch.addEventListener('blur', () => {
        setTimeout(() => {
            if (occList) occList.style.display = 'none';
            const match = window.occArray.find(o => o.name === occSearch.value.trim());
            if (match) {
                if (occHidden) occHidden.value = match.name;
                codeSearch.value = match.code;
                if (codeHidden) codeHidden.value = match.code;
            } else if (!occSearch.value.trim()) {
                if (occHidden) occHidden.value = '';
                codeSearch.value = '';
                if (codeHidden) codeHidden.value = '';
            }
        }, 200);
    });

    codeSearch.addEventListener('focus', () => {
        renderList(codeList, window.occArray, true);
        if (codeList) codeList.style.display = 'block';
    });

    codeSearch.addEventListener('input', (e) => {
        const val = e.target.value.trim().toLowerCase();
        const filtered = val ? window.occArray.filter(o => o.code.toLowerCase().includes(val)) : window.occArray;
        renderList(codeList, filtered, true);
        if (codeList) codeList.style.display = 'block';
    });

    codeSearch.addEventListener('blur', () => {
        setTimeout(() => {
            if (codeList) codeList.style.display = 'none';
            const match = window.occArray.find(o => o.code === codeSearch.value.trim());
            if (match) {
                occSearch.value = match.name;
                if (occHidden) occHidden.value = match.name;
                if (codeHidden) codeHidden.value = match.code;
            } else if (!codeSearch.value.trim()) {
                occSearch.value = '';
                if (occHidden) occHidden.value = '';
                if (codeHidden) codeHidden.value = '';
            }
        }, 200);
    });
}

document.addEventListener('DOMContentLoaded', initOccupationsAutocomplete);
